files.content:
* {
  box-sizing: border-box;
  margin: 0;
}

.page {
  gap: 25px;
  min-height: calc(100vh - 100px);
  padding: 50px;
  color: #000;
  font-family: 'Open Sans', sans-serif;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.places__header {
  margin-block-start: 0;
  margin-block-end: 50px;
  font-weight: 800;
  font-size: 45px;
  text-transform: uppercase;
}

.places__list {
  display: flex;
  flex-wrap: wrap;
  gap: 25px;
  padding: 0;
  list-style-type: none;
}

.places__item {
  flex-grow: 1;
  border: 1px solid #000;
  padding: 5px 20px;
  font-weight: 800;
  font-size: 18px;
  line-height: 1.4;
  text-transform: uppercase;

  /* Укажите элементам занимать всё доступное пространство */
  background-color: #ffc802;
}
